_message_reduce_kernel = None
_message_batch_graph_pools = weakref.WeakKeyDictionary()
_message_fault_graph_pools = weakref.WeakKeyDictionary()
_message_batch_numeric_pools = weakref.WeakKeyDictionary()

class _MessageCudaKernel:
    def __init__(self):
        if not torch.cuda.is_initialized():
            raise RuntimeError("Caller must initialize Torch CUDA first")
        self.driver = ct.WinDLL("nvcuda.dll")
        signatures = {
            "cuCtxGetCurrent": [ct.POINTER(ct.c_void_p)],
            "cuModuleLoadData": [ct.POINTER(ct.c_void_p), ct.c_void_p],
            "cuModuleGetFunction": [ct.POINTER(ct.c_void_p), ct.c_void_p, ct.c_char_p],
            "cuLaunchKernel": [ct.c_void_p] + [ct.c_uint] * 7 +
                              [ct.c_void_p, ct.POINTER(ct.c_void_p), ct.c_void_p],
            "cuModuleUnload": [ct.c_void_p],
        }
        for name, args in signatures.items():
            function = getattr(self.driver, name)
            function.argtypes = args
            function.restype = ct.c_int
        self.context = ct.c_void_p()
        self._check(self.driver.cuCtxGetCurrent(ct.byref(self.context)))
        if not self.context.value:
            raise RuntimeError("No existing current CUDA context")
        self.ptx = ct.create_string_buffer(_MESSAGE_REDUCE_PTX)
        self.module = ct.c_void_p()
        self._check(self.driver.cuModuleLoadData(ct.byref(self.module), self.ptx))
        self.function = ct.c_void_p()
        try:
            self._check(self.driver.cuModuleGetFunction(
                ct.byref(self.function), self.module, b"exact_fixedstar_sum_mean_fp32"))
        except Exception:
            self.driver.cuModuleUnload(self.module)
            self.module = None
            raise

    @staticmethod
    def _check(result):
        if result:
            raise RuntimeError("CUDA driver error %d" % result)

    def launch(self, arguments, count, stream, block=128):
        """arguments are ctypes scalar instances; pointers use c_uint64.

        Caller validates tensor shape/dtype/index bounds, no-grad constraints,
        device/context match, and keeps input/output storage alive on stream.
        """
        if self.module is None:
            raise RuntimeError("Module is closed")
        current = ct.c_void_p()
        self._check(self.driver.cuCtxGetCurrent(ct.byref(current)))
        if current.value != self.context.value:
            raise RuntimeError("CUDA context changed")
        if count == 0:
            return
        parameters = (ct.c_void_p * len(arguments))(
            *(ct.addressof(argument) for argument in arguments))
        self._check(self.driver.cuLaunchKernel(
            self.function, (count + block - 1) // block, 1, 1,
            block, 1, 1, 0, ct.c_void_p(stream), parameters, None))


def _message_reduce_eligible(encoder):
    values = tuple(encoder.parameters())
    return (values and all(v.is_cuda and v.dtype == torch.float32 and not v.requires_grad for v in values)
            and not any(m.training for m in encoder.modules()))

def _message_reduce_positions(nodes, targets):
    groups = [[] for _ in range(nodes)]
    for position, target in enumerate(targets):
        groups[target].append(position)
    if max(map(len, groups), default=0) > 5:
        return None
    positions = [group + [-1] * (5 - len(group)) for group in groups]
    return positions, [len(group) for group in groups]

@contextmanager
def _message_capture_scope(encoder, edges, all_edges, nodes):
    global _message_reduce_kernel
    if _message_reduce_kernel is None:
        _message_reduce_kernel = _MessageCudaKernel()
    kernel = _message_reduce_kernel
    active = ContextVar('native_message_capture', default=None)
    maps = OrderedDict()
    replay = _message_reencode_capture.get()
    if replay is not None:
        maps.update(replay['tables'])

    def index_key(index):
        return (index.data_ptr(), index._version, tuple(index.shape), tuple(index.stride()), index.device)

    def register(scope, edges, targets):
        scope['indices'][index_key(edges[1])] = (targets, edges)

    @contextmanager
    def scope_for(encoder, edges, all_edges, nodes):
        if (not _message_reduce_eligible(encoder) or any(a == b for a, b in zip(*all_edges))):
            yield
            return
        targets = tuple(all_edges[1])
        if _message_reduce_positions(nodes, targets) is None:
            yield
            return
        scope = dict(nodes=nodes, targets=targets, indices={}, resources={})
        if replay is not None:
            register(scope, replay['edges'], tuple(replay['all_edges'][1]))
        register(scope, edges, targets)
        token = active.set(scope)
        try:
            yield
        finally:
            active.reset(token)

    gat = importlib.import_module('torch_geometric.nn.conv.gat_conv')
    original_remove, original_add = gat.remove_self_loops, gat.add_self_loops

    def remove(edges, attributes=None):
        if replay is not None:
            # Both recorded edge sets were checked to contain no self loops.
            result = (edges, attributes)
        else:
            result = original_remove(edges, attributes)
        scope = active.get()
        known = None if scope is None else scope['indices'].get(index_key(edges[1]))
        if known is not None:
            register(scope, result[0], known[0])
        return result

    def add(edges, attributes=None, fill_value=None, num_nodes=None):
        result = original_add(edges, attributes, fill_value, num_nodes)
        scope = active.get()
        known = None if scope is None else scope['indices'].get(index_key(edges[1]))
        if replay is not None and known is not None and num_nodes == scope['nodes']:
            register(scope, result[0], known[0] + tuple(range(num_nodes)))
        elif known is not None and known[0] == scope['targets'] and num_nodes == scope['nodes']:
            register(scope, result[0], known[0] + tuple(range(num_nodes)))
        return result

    def wrapper(native):
        def scatter(src, index, dim=0, dim_size=None, reduce='sum'):
            scope = active.get()
            known = None if scope is None else scope['indices'].get(index_key(index))
            if (known is None or reduce not in ('sum', 'add', 'mean')
                    or src.ndim == 0 or dim % src.ndim != 0 or dim_size != scope['nodes']
                    or not src.is_cuda or src.dtype != torch.float32 or not src.is_contiguous()
                    or src.requires_grad or torch.is_grad_enabled() or index.dtype != torch.int64
                    or src.shape[0] != len(known[0]) or src.device != index.device
                    or src.device.index != torch.cuda.current_device()):
                return native(src, index, dim, dim_size, reduce)
            targets = known[0]
            key = (scope['nodes'], targets, src.device)
            if key not in maps:
                data = _message_reduce_positions(scope['nodes'], targets)
                if data is None:
                    return native(src, index, dim, dim_size, reduce)
                maps[key] = (torch.tensor(data[0], dtype=torch.int64, device=src.device),
                             torch.tensor(data[1], dtype=torch.int32, device=src.device))
                if len(maps) > 64:
                    maps.popitem(last=False)
            maps.move_to_end(key)
            positions, degrees = maps[key]
            # Captured graphs retain raw addresses, so their owner must be able
            # to keep topology tensors alive after this LRU evicts an entry.
            scope['resources'][key] = (positions, degrees)
            output = src.new_empty((dim_size, *src.shape[1:]))
            channels = 1
            for size in src.shape[1:]:
                channels *= size
            stream = torch.cuda.current_stream(src.device)
            args = [ct.c_uint64(t.data_ptr()) for t in (src, output, positions, degrees)]
            args += [ct.c_int64(dim_size), ct.c_int64(channels), ct.c_int64(5), ct.c_int(reduce == 'mean')]
            kernel.launch(args, output.numel(), stream.cuda_stream)
            for tensor in (src, output, positions, degrees):
                tensor.record_stream(stream)
            return output
        return scatter

    with ExitStack() as stack:
        for name in ('torch_geometric.utils._scatter', 'torch_geometric.utils._softmax',
                     'torch_geometric.utils.loop', 'torch_geometric.nn.aggr.base',
                     'torch_geometric.utils'):
            module = importlib.import_module(name)
            native = module.scatter
            module.scatter = wrapper(native)
            stack.callback(setattr, module, 'scatter', native)
        gat.remove_self_loops, gat.add_self_loops = remove, add
        stack.callback(setattr, gat, 'remove_self_loops', original_remove)
        stack.callback(setattr, gat, 'add_self_loops', original_add)
        with scope_for(encoder, edges, all_edges, nodes):
            yield lambda: tuple(tensor for pair in active.get()['resources'].values() for tensor in pair)


def _message_graph_supported():
    if not (sys.platform == 'win32' and torch.cuda.is_initialized()
            and torch.version.git_version == '32f585d9346e316e554c8d9bf7548af9f62141fc'
            and torch.are_deterministic_algorithms_enabled()
            and torch.cuda.current_device() == 0
            and torch.cuda.get_device_capability() == (8, 9)):
        return False
    if _message_reduce_kernel is None:
        return True
    current = ct.c_void_p()
    return (_message_reduce_kernel.driver.cuCtxGetCurrent(ct.byref(current)) == 0
            and current.value == _message_reduce_kernel.context.value)


_REENCODE_FIELDS = ('x', 'message_edge_index1', 'message_edge_index2',
                    'message_edge_attr1', 'message_edge_attr2')


def _message_reencode_inputs(cpu, edges1, edges2, device):
    # One aligned byte upload preserves float/int representations and edge order.
    nodes, tables = len(cpu.x), {}
    for edges in (edges1, edges2):
        targets = tuple(edges[1])
        for target in (targets, targets + tuple(range(nodes))):
            positions, degrees = _message_reduce_positions(nodes, target)
            tables[(nodes, target, device)] = (
                torch.tensor(positions, dtype=torch.int64),
                torch.tensor(degrees, dtype=torch.int32))
    fields = {name: cpu[name] for name in _REENCODE_FIELDS}
    items = list(fields.items()) + [((key, index), tensor)
        for key, pair in tables.items() for index, tensor in enumerate(pair)]
    offsets, size = {}, 0
    for key, tensor in items:
        size = (size + 255) // 256 * 256
        offsets[key] = size
        size += tensor.numel() * tensor.element_size()
    host = torch.zeros(size, dtype=torch.uint8, pin_memory=True)
    views = {}
    for key, tensor in items:
        views[key] = host[offsets[key]:offsets[key] + tensor.numel() * tensor.element_size()].view(
            tensor.dtype).view(tensor.shape)
        views[key].copy_(tensor)
    gpu = host.to(device, non_blocking=True)
    gpu_views = {key: gpu[offsets[key]:offsets[key] + tensor.numel() * tensor.element_size()].view(
        tensor.dtype).view(tensor.shape) for key, tensor in items}
    return Data(**{name: gpu_views[name] for name in fields}), dict(
        host=host, gpu=gpu, views=views,
        tables={key: tuple(gpu_views[(key, index)] for index in range(2)) for key in tables})


def _message_reencode_refresh(bank, cpu, edges1, edges2):
    packed, nodes = bank['packed'], len(cpu.x)
    for name in _REENCODE_FIELDS:
        packed['views'][name].copy_(cpu[name])
    mapping = {}
    for old, new in zip(bank['topology'], (edges1[1], edges2[1])):
        mapping[old] = tuple(new)
        mapping[old + tuple(range(nodes))] = tuple(new) + tuple(range(nodes))
    for key in packed['tables']:
        values = _message_reduce_positions(nodes, mapping[key[1]])
        for index, dtype in ((0, torch.int64), (1, torch.int32)):
            packed['views'][(key, index)].copy_(torch.tensor(values[index], dtype=dtype))
    packed['gpu'].copy_(packed['host'], non_blocking=True)


def _message_reencode_graph(encoder, cpu):
    """Frozen decision inference only; replay and optimizer tensors stay unchanged."""
    if not _message_graph_supported() or torch.is_grad_enabled():
        return None
    origin = _message_origins.get(encoder)
    source = None if origin is None else origin[0]()
    if (source is None or _message_batch_kind(encoder) is None
            or origin[2] != _message_signature(encoder)):
        return None
    device = next(encoder.parameters()).device
    if device != torch.device('cuda', torch.cuda.current_device()):
        return None
    for name in _REENCODE_FIELDS:
        value = cpu[name]
        dtype = torch.int64 if 'index' in name else torch.float32
        if value.device.type != 'cpu' or value.dtype != dtype:
            return None
    nodes = len(cpu.x)
    edges1, edges2 = cpu.message_edge_index1.tolist(), cpu.message_edge_index2.tolist()
    for edges in (edges1, edges2):
        if (any(a == b for a, b in zip(*edges))
                or _message_reduce_positions(nodes, tuple(edges[1]) + tuple(range(nodes))) is None):
            return None
    # Equal target sets share reduction tables at capture. Preserve that alias
    # relationship when reusing a shape for a different recorded topology.
    key = (type(encoder), tuple(cpu.x.shape), cpu.x.dtype,
           tuple(cpu.message_edge_index1.shape), tuple(cpu.message_edge_index2.shape),
           (edges1[1] == edges2[1],
            tuple(edges1[1]) == tuple(edges2[1]) + tuple(range(nodes)),
            tuple(edges2[1]) == tuple(edges1[1]) + tuple(range(nodes))),
           tuple(cpu.message_edge_attr1.shape),
           tuple(cpu.message_edge_attr2.shape), repr(encoder.conv1), repr(encoder.conv2))
    pool = _message_reencode_pools.setdefault(source, OrderedDict())
    bank = pool.get(key)
    if bank is None:
        with torch.random.fork_rng(devices=[device.index]):
            prepared = deepcopy(encoder).eval().requires_grad_(False)
        data, packed = _message_reencode_inputs(cpu, edges1, edges2, device)
        token = _message_reencode_capture.set(dict(
            edges=data.message_edge_index2, all_edges=edges2, tables=packed['tables']))
        try:
            with _message_capture_scope(prepared, data.message_edge_index1, edges1, nodes) as resources:
                stream = _message_shared_warmup_stream(source, device)
                stream.wait_stream(torch.cuda.current_stream(device))
                with torch.cuda.stream(stream):
                    for _ in range(3):
                        prepared(data)
                torch.cuda.current_stream(device).wait_stream(stream)
                graph = torch.cuda.CUDAGraph()
                with torch.cuda.graph(graph):
                    out = prepared(data)[:4].reshape(1, -1)
                bank = dict(model=prepared, data=data, graph=graph, out=out,
                            generation=origin[1], resources=resources(), packed=packed,
                            topology=(tuple(edges1[1]), tuple(edges2[1])))
        finally:
            _message_reencode_capture.reset(token)
        pool[key] = bank
        if len(pool) > 64:
            pool.popitem(last=False)
    else:
        _message_reencode_refresh(bank, cpu, edges1, edges2)
        if bank['generation'] != origin[1]:
            bank['model'].load_state_dict(encoder.state_dict())
            bank['generation'] = origin[1]
    pool.move_to_end(key)
    bank['graph'].replay()
    # A fresh CPU copy keeps past experiences independent of reusable GPU banks.
    return bank['out'].cpu()


def _message_pack_outputs(first, second, combined, indices):
    # Pure copies: preserve each original 1-D JK projection and float32 bits.
    final = torch.stack(combined) if combined is not None else second.index_select(0, indices)
    return torch.cat((first.index_select(0, indices), final), dim=1)

def _message_batch_graph(encoder, x, edges, attrs, offsets, recipes, raw_dim, hidden_dim, kind, all_edges):
    if not _message_graph_supported():
        return None
    origin = _message_origins.get(encoder)
    source = None if origin is None else origin[0]()
    valid = (source is not None and origin[2] == _message_signature(encoder)
             and _message_batch_kind(encoder) is not None and not torch.is_grad_enabled())
    values = [v for raw, neighbors, attributes in recipes
              for seq in (raw, *neighbors, *attributes) for v in seq]
    valid = valid and x.device.index == 0 and all(t.device.index == 0
        for t in (*encoder.parameters(), *encoder.buffers()))
    valid = valid and all(math.isfinite(v) and abs(v) <= 3.4028234663852886e38 for v in values)
    is_gat = type(encoder).__name__ == 'GATMessageEncoder'
    if is_gat:
        valid = valid and (encoder.conv1.fill_value == encoder.conv2.fill_value
                           and encoder.conv1.add_self_loops and encoder.conv2.add_self_loops
                           and not any(a == b for a, b in zip(*all_edges)))
    if not valid:
        return None
    structure = tuple((n, tuple(t.shape), tuple(t.stride()), str(t.dtype), str(t.device))
                      for n, t in encoder.state_dict().items())
    key = (type(encoder), tuple(1 + len(r[1]) for r in recipes), tuple(offsets),
           tuple(map(tuple, all_edges)), tuple(x.shape), tuple(x.stride()), x.device, x.dtype,
           None if attrs is None else (tuple(attrs.shape), tuple(attrs.stride())),
           structure, repr(encoder.conv1), repr(encoder.conv2), True, True)
    pool = _message_batch_graph_pools.setdefault(source, OrderedDict())
    bank = pool.get(key)
    hidden_values = []
    for _, neighbors, _ in recipes:
        hidden_values.extend([[0.] * hidden_dim,
                              *[v[raw_dim:raw_dim + hidden_dim] for v in neighbors]])
    # Match the original host float -> float32 conversion for all neighbors.
    h = torch.tensor(hidden_values, dtype=torch.float32, device=x.device)
    if bank is None:
        import torch_geometric.nn.conv.gat_conv as gat
        # PyG Linear.__deepcopy__ invokes a constructor/reset_parameters,
        # consuming CPU RNG even for CUDA models before copying weights.
        # A frozen graph's private clone must not advance simulation RNG.
        with torch.random.fork_rng(devices=[x.device.index]):
            prepared = deepcopy(encoder).eval().requires_grad_(False)
        if is_gat:
            prepared.conv1.add_self_loops = prepared.conv2.add_self_loops = False
        sx, sh, se = x.clone(), h, edges.clone()
        sa = None if attrs is None else attrs.clone()
        indices = torch.tensor(offsets, dtype=torch.long, device=x.device)
        with _message_capture_scope(prepared, se, all_edges, len(x)) as captured_resources:
            ge, ga = se, sa

            def operation():
                nonlocal ge, ga
                if is_gat:
                    # Native batch edges have no self loops. Original remove
                    # would retain every row in its original order, so use
                    # that verified static topology and capture original add
                    # and fill arithmetic; attrs are refreshed before replay.
                    ge, ga = gat.add_self_loops(se, sa,
                        fill_value=prepared.conv1.fill_value, num_nodes=len(x))
                first = prepared.aggregate_stage(sx, ge, 1, ga)
                sh.index_copy_(0, indices, first.index_select(0, indices))
                second = prepared.aggregate_stage(sh, ge, 2, ga)
                combined = ([prepared.combine_hops(sx[o], first[o], second[o]) for o in offsets]
                            if hasattr(prepared, 'combine_hops') else None)
                return first, second, combined, _message_pack_outputs(first, second, combined, indices)

            stream = _message_shared_warmup_stream(source, x.device)
            stream.wait_stream(torch.cuda.current_stream(x.device))
            with torch.cuda.stream(stream):
                for _ in range(3):
                    operation()
            torch.cuda.current_stream(x.device).wait_stream(stream)
            graph = torch.cuda.CUDAGraph()
            with torch.cuda.graph(graph):
                outputs = operation()
            resources = captured_resources()
        # Keep every captured input, model and topology tensor alive.
        bank = dict(model=prepared, x=sx, h=sh, edges=se, attrs=sa,
                    graph_edges=ge, graph_attrs=ga, indices=indices,
                    graph=graph, outputs=outputs, generation=origin[1],
                    topology_resources=resources)
        pool[key] = bank
        if len(pool) > 16:
            pool.popitem(last=False)
    else:
        bank['x'].copy_(x)
        bank['h'].copy_(h)
        if bank['generation'] != origin[1]:
            # load_state_dict copies into the existing captured storage.
            bank['model'].load_state_dict(encoder.state_dict())
            bank['generation'] = origin[1]
        if attrs is not None:
            bank['attrs'].copy_(attrs)
    pool.move_to_end(key)
    bank['graph'].replay()
    return bank['outputs'][3].cpu().tolist()


def _message_fault_graph(encoder, raw, edges, raw_value):
    if not _message_graph_supported():
        return None
    origin = _message_origins.get(encoder)
    source = None if origin is None else origin[0]()
    valid = (source is not None and origin[2] == _message_signature(encoder)
             and _message_batch_kind(encoder) is not None and not torch.is_grad_enabled()
             and tuple(raw.shape) == (1, 6) and tuple(edges.shape) == (2, 0)
             and all(math.isfinite(v) and abs(v) <= 3.4028234663852886e38 for v in raw_value))
    valid = valid and raw.device.index == 0 and all(t.device.index == 0
        for t in (*encoder.parameters(), *encoder.buffers()))
    is_gat = type(encoder).__name__ == 'GATMessageEncoder'
    if is_gat:
        valid = valid and (encoder.conv1.fill_value == encoder.conv2.fill_value
                           and encoder.conv1.add_self_loops and encoder.conv2.add_self_loops)
    if not valid:
        return None
    structure = tuple((n, tuple(t.shape), tuple(t.stride()), t.dtype, t.device)
                      for n, t in encoder.state_dict().items())
    key = (type(encoder), structure, repr(encoder.conv1), repr(encoder.conv2))
    pool = _message_fault_graph_pools.setdefault(source, {})
    bank = pool.get(key)
    if bank is None:
        import torch_geometric.nn.conv.gat_conv as gat
        with torch.random.fork_rng(devices=[raw.device.index]):
            prepared = deepcopy(encoder).eval().requires_grad_(False)
        if is_gat:
            prepared.conv1.add_self_loops = prepared.conv2.add_self_loops = False
        sr, se = raw.clone(), edges.clone()
        with _message_capture_scope(prepared, se, [[], []], 1) as captured_resources:
            if is_gat:
                # Original GATMessageEncoder(None) first makes empty 2-D
                # zero attrs, then the original convolution fills its loop.
                zero_attrs = sr.new_zeros((0, 2))
                stripped_e, stripped_a = gat.remove_self_loops(se, zero_attrs)
                ge, ga = gat.add_self_loops(stripped_e, stripped_a,
                    fill_value=prepared.conv1.fill_value, num_nodes=1)
            else:
                ge, ga = se, None

            def operation():
                first = prepared.aggregate_stage(sr, ge, 1, ga)
                second = prepared.aggregate_stage(first, ge, 2, ga)
                if hasattr(prepared, 'combine_hops'):
                    # Fault path is 2-D; do not substitute batch-path 1-D JK.
                    second = prepared.combine_hops(sr, first, second)
                return torch.cat((first[0], second[0]))

            stream = _message_shared_warmup_stream(source, raw.device)
            stream.wait_stream(torch.cuda.current_stream(raw.device))
            with torch.cuda.stream(stream):
                for _ in range(3):
                    operation()
            torch.cuda.current_stream(raw.device).wait_stream(stream)
            graph = torch.cuda.CUDAGraph()
            with torch.cuda.graph(graph):
                packed = operation()
            resources = captured_resources()
        bank = dict(model=prepared, raw=sr, edges=se, graph_edges=ge, graph_attrs=ga,
                    graph=graph, packed=packed, topology_resources=resources,
                    generation=origin[1])
        # A source has one supported fault shape; discard old structures.
        pool.clear()
        pool[key] = bank
    else:
        bank['raw'].copy_(raw)
        if bank['generation'] != origin[1]:
            bank['model'].load_state_dict(encoder.state_dict())
            bank['generation'] = origin[1]
    bank['graph'].replay()
    # Python numbers are immutable, so native numeric-cache ownership is safe.
    return tuple(bank['packed'].cpu().tolist())


def _message_prepare_batch(encoder, recipes, kind):
    if not _message_graph_supported():
        return None, None, None
    origin = _message_origins.get(encoder)
    if origin is None or origin[2] != _message_signature(encoder):
        return None, None, None
    source = origin[0]()
    if source is None or any(m.training for m in encoder.modules()) or any(p.requires_grad for p in encoder.parameters()):
        return None, None, None
    if any(t.device.index != 0 for t in (*encoder.parameters(), *encoder.buffers())):
        return None, None, None
    parts = []
    width = encoder.conv1.in_channels + encoder.conv1.out_channels
    for raw, neighbors, attributes in recipes:
        values = [*raw, *(v for message in neighbors for v in message[:width]),
                  *(v for attribute in attributes for v in attribute)]
        if not all(math.isfinite(v) and abs(v) <= 3.4028234663852886e38 for v in values):
            return None, None, None
        parts.append((len(raw), len(neighbors), struct.pack(f'{len(values)}f', *values)))
    pool = _message_batch_numeric_pools.setdefault(source, OrderedDict())
    generation = origin[1]
    if generation not in pool:
        pool[generation] = OrderedDict()
        if len(pool) > 2:
            pool.popitem(last=False)
    pool.move_to_end(generation)
    cache = pool[generation]
    key = (kind, tuple(parts))
    numeric = cache.get(key)
    if numeric is not None:
        cache.move_to_end(key)
    return cache, key, numeric


def _message_reconstruct_batch(self, recipes, numeric, version, model_version):
    result = []
    for (raw, neighbors, attributes), value in zip(recipes, numeric):
        raw_trace = (0, tuple(raw), self.env.now, version)
        trace1 = (1, raw_trace, tuple(m.trace[0] for m in neighbors),
                  self.env.now, version, model_version, tuple(attributes))
        trace2 = (2, trace1, tuple(m.trace[1] for m in neighbors),
                  self.env.now, version, model_version, tuple(attributes))
        result.append(GraphSAGEMessage(raw + list(value), (raw_trace, trace1, trace2), model_version))
    return result

def _message_remember_batch(cache, key, result, recipes):
    if cache is None:
        return
    cache[key] = tuple(tuple(message[len(raw):]) for message, (raw, _, _) in zip(result, recipes))
    if len(cache) > 16384:
        cache.popitem(last=False)


class GraphSAGEMessage(list):
    """Local training record; only list(message) goes through the transport."""

    def __init__(self, value, trace, model_version=0):
        super().__init__(value)
        self.trace = trace
        self.model_version = model_version


class GraphSAGEEncoder(BaseGraphSAGEEncoder):
    """Two mean-aggregation layers; each applies LeakyReLU before sharing."""

    aligned_graphsage_policy = True
    _apply = _message_encoder_apply

    def __init__(self, in_channels, hidden_channels, edge_dim, out_channels):
        super().__init__(in_channels, hidden_channels, edge_dim, out_channels)
        self.output_dim = in_channels + hidden_channels + out_channels

    def communication_snapshot(self, env, version):
        # Shared by all satellites using this encoder in this simulation round.
        # Keep snapshots on the environment, outside the trainable module tree.
        if not hasattr(env, 'graphsage_model_snapshots'):
            env.graphsage_model_snapshots = {}
        snapshots = env.graphsage_model_snapshots.setdefault(self, {})
        if version not in snapshots:
            snapshot = deepcopy(self).eval().requires_grad_(False)
            snapshot.model_version = version
            snapshots[version] = snapshot
            if _message_batch_kind(snapshot) is not None:
                _message_origins[snapshot] = (
                    weakref.ref(self), _message_signature(self), _message_signature(snapshot))
            for old in list(snapshots):
                if old < version - 1:
                    del snapshots[old]
        return snapshots[version]

    @staticmethod
    def shuffle_for_policy(state):
        data, other = state
        indices = np.random.permutation(4)
        shuffled = data.clone()
        order = torch.cat([torch.as_tensor(indices, dtype=torch.long),
                           torch.arange(4, data.x.size(0))])
        inverse = torch.empty_like(order)
        inverse[order] = torch.arange(order.numel())
        for field in ('x', 'message_raw_time', 'message_raw_version', 'message_layer1_model_version'):
            shuffled[field] = data[field][order]
        for field in ('message_edge_index1', 'message_edge_index2'):
            shuffled[field] = inverse[data[field]]
        shuffled.decision_embeddings = data.decision_embeddings.view(4, -1)[indices].reshape(1, -1)
        shuffled.message_model_version = data.message_model_version[:, indices]
        other = np.asarray(other).copy()
        other[:8] = other[:8].reshape(4, 2)[indices].reshape(-1)
        return [shuffled, other], indices

    def aggregate_stage(self, x, edge_index, layer, edge_attr=None):
        convolution = self.conv1 if layer == 1 else self.conv2
        return F.leaky_relu(convolution(x, edge_index))

    def forward(self, data):
        # Re-encode recorded message inputs with CURRENT parameters for training.
        # decision_embeddings retains the actual historical decision values.
        if not hasattr(data, 'message_edge_index1'):
            raise ValueError('GraphSAGE replay requires received-message history')
        layer1 = self.aggregate_stage(data.x, data.message_edge_index1, layer=1)
        layer2 = self.aggregate_stage(layer1, data.message_edge_index2, layer=2)
        return torch.cat([data.x, layer1, layer2], dim=-1)

    @staticmethod
    def replay_data(messages):
        # The first four nodes are the four decision directions. Duplicate
        # leaves retain different versions instead of merging by satellite ID.
        traces = [message.trace for message in messages]
        values, times, versions, model_versions = [], [], [], []
        edges1, edges2 = [], []
        attributes1, attributes2 = [], []

        def raw_node(trace, model_version=-1):
            index = len(values)
            values.append(trace[1])
            times.append(trace[2])
            versions.append(trace[3])
            model_versions.append(model_version)
            return index

        for trace in traces:
            raw_node(trace[0], trace[1][5])

        def layer1_edges(trace, target):
            for index, raw in enumerate(trace[2]):
                edges1.append((raw_node(raw), target))
                attributes1.append(trace[6][index] if len(trace) > 6 else (0., 0.))

        for target, trace in enumerate(traces):
            layer1_edges(trace[1], target)
            for position, neighbor in enumerate(trace[2][2]):
                index = raw_node(neighbor[1], neighbor[5])
                layer1_edges(neighbor, index)
                edges2.append((index, target))
                attributes2.append(trace[2][6][position] if len(trace[2]) > 6 else (0., 0.))

        def edge_tensor(edges):
            return (torch.tensor(edges, dtype=torch.long).t().contiguous()
                    if edges else torch.empty((2, 0), dtype=torch.long))

        return Data(
            x=torch.tensor(values, dtype=torch.float),
            message_edge_index1=edge_tensor(edges1),
            message_edge_index2=edge_tensor(edges2),
            message_edge_attr1=torch.tensor(attributes1, dtype=torch.float).reshape(-1, 2),
            message_edge_attr2=torch.tensor(attributes2, dtype=torch.float).reshape(-1, 2),
            message_raw_time=torch.tensor(times, dtype=torch.float64),
            message_raw_version=torch.tensor(versions, dtype=torch.long),
            message_layer1_model_version=torch.tensor(model_versions, dtype=torch.long),
            message_model_version=torch.tensor(
                [[message.model_version for message in messages]], dtype=torch.long),
            decision_embeddings=torch.tensor([sum((list(m) for m in messages), [])], dtype=torch.float),
        )


class GraphSAGESatellite(simulation.Satellite_with_Computing):
    """Exchange one [raw, layer1, layer2] message per resource-update tick."""

    aligned_graphsage_policy = True

    def _fresh_message(self, cache, neighbor, version, previous_only=True):
        records = cache.get(neighbor, ())
        for cached_version, received_at, value in reversed(records):
            allowed = cached_version < version if previous_only else cached_version <= version
            # A delivery exactly on the boundary is not eligible this tick,
            # regardless of which SimPy process happens to execute first.
            before_tick = not previous_only or received_at < version * self.state_update_period - 1e-9
            if allowed and before_tick and self.env.now <= received_at + self.heartbeat_timeout:
                return value
        return None

    def send_gnn_message(self, neighbor, version, value):
        # Simulator-only provenance stays outside the numeric network payload.
        if not hasattr(self.propagator, 'gnn_training_metadata'):
            self.propagator.gnn_training_metadata = {}
        metadata = self.propagator.gnn_training_metadata
        key = (self.name, neighbor, 'pipeline', version)
        metadata[key] = (value.trace, value.model_version)
        try:
            yield from self.propagator.send_gnn_embedding_message(
                self.name, neighbor, 'pipeline', version, list(value))
        finally:
            metadata.pop(key, None)

    def valid_resource_message(self, stage, value):
        expected = (self.gnn.output_dim if isinstance(self.gnn, GraphSAGEEncoder)
                    else self.gnn.conv1.in_channels + self.gnn.conv1.out_channels + self.gnn.output_dim)
        return stage == 'pipeline' and len(value) == expected and all(math.isfinite(v) for v in value)

    def receive_gnn_embedding_message(self, neighbor, stage, version, value):
        if not self.valid_resource_message(stage, value):
            return
        if not hasattr(self, 'gnn_pipeline_messages'):
            self.gnn_pipeline_messages = {}
        records = self.gnn_pipeline_messages.setdefault(neighbor, [])
        if records and version <= records[-1][0]:
            return
        if isinstance(value, GraphSAGEMessage):
            trace, model_version = value.trace, value.model_version
        else:
            trace, model_version = self.propagator.gnn_training_metadata[
                (neighbor, self.name, stage, version)]
        message = GraphSAGEMessage(value, trace, model_version)
        records.append((version, self.env.now, message))
        del records[:-2]
        self.gnn_active_neighbor_embeddings[neighbor] = message
        self.last_heartbeat[neighbor] = self.env.now
        self.neighbor_states[neighbor] = list(value[:self.gnn.conv1.in_channels])
        self.on_neighbor_state_received(neighbor, sent_at=version * self.state_update_period)

    def _projected_neighbor_memory_remain(self, neighbor, packet_size):
        cache = getattr(self, 'gnn_pipeline_messages', {})
        if (not self.neighbor_is_alive(neighbor)
                or self._fresh_message(cache, neighbor, self.gnn_cycle_version, False) is None):
            return -float('inf')
        return super()._projected_neighbor_memory_remain(neighbor, packet_size)

    def current_fault_node_state(self, recipient=None):
        cache = getattr(self, 'gnn_pipeline_messages', {})
        valid = [value for neighbor in self.neighbors if neighbor != recipient
                 for value in [self._fresh_message(cache, neighbor, self.gnn_cycle_version)]
                 if value is not None]
        raw_dim = self.gnn.conv1.in_channels
        if not valid:
            return [1, 0, 0, 1, 1] + ([0] if raw_dim == 6 else [])
        factor = self.fault_fill_multiplier
        use_mean = getattr(self, 'fault_compute_double_mean', True)
        means = [sum(value[i] for value in valid) / len(valid) for i in (2, 3, 4)]
        clip = simulation._clip_normalized
        ability = clip(means[0] / factor) if use_mean else 0
        wait = clip(means[1] * factor) if use_mean else 1
        transmission = clip(means[2] * (factor if use_mean else 2))
        result = [1, 0, ability, wait, transmission]
        if raw_dim == 6:
            result.append(clip(sum(value[5] for value in valid) / len(valid) / factor)
                          if use_mean else 0)
        return result

    def _fault_message(self, raw_value=None):
        encoder = getattr(self, 'gnn_cycle_encoder', self.gnn)
        device = next(encoder.parameters()).device
        raw_value = self.current_fault_node_state() if raw_value is None else raw_value
        cache = _message_cache(encoder)
        key = None
        if cache is not None and all(math.isfinite(v) and abs(v) <= 3.4028234663852886e38 for v in raw_value):
            key = struct.pack(f'{len(raw_value)}f', *raw_value)
        numeric = cache.get(key) if key is not None else None
        if numeric is None:
            raw = torch.tensor([raw_value], dtype=torch.float, device=device)
            edges = torch.empty((2, 0), dtype=torch.long, device=device)
            with torch.no_grad():
                numeric = _message_fault_graph(encoder, raw, edges, raw_value)
                if numeric is None:
                    layer1 = encoder.aggregate_stage(raw, edges, layer=1)
                    layer2 = encoder.aggregate_stage(layer1, edges, layer=2)
                    if hasattr(encoder, 'combine_hops'):
                        layer2 = encoder.combine_hops(raw, layer1, layer2)
                    numeric = tuple(layer1[0].cpu().tolist() + layer2[0].cpu().tolist())
            if key is not None:
                cache[key] = numeric
                if len(cache) > 4096:
                    cache.popitem(last=False)
        elif key is not None:
            cache.move_to_end(key)
        model_version = getattr(encoder, 'model_version', 0)
        raw_trace = (0, tuple(raw_value), self.env.now, self.gnn_cycle_version)
        trace1 = (1, raw_trace, (), self.env.now, self.gnn_cycle_version, model_version)
        trace2 = (2, trace1, (), self.env.now, self.gnn_cycle_version, model_version)
        return GraphSAGEMessage(raw_value + list(numeric),
                                (raw_trace, trace1, trace2), model_version)

    def _message_reference_batch(self, version, recipients, kind):
        encoder = self.gnn_cycle_encoder
        device = next(encoder.parameters()).device
        raw_dim, hidden_dim = encoder.conv1.in_channels, encoder.conv1.out_channels
        model_version = getattr(encoder, 'model_version', 0)
        histories = getattr(self, 'gnn_pipeline_messages', {})
        recipes, all_x, all_edges, all_attrs, offsets = [], [], [[], []], [], []
        for recipient in recipients:
            raw = self.current_gnn_raw_state()
            records = [(neighbor, value) for neighbor in self.neighbors if neighbor != recipient
                       for value in [self._fresh_message(histories, neighbor, version)] if value is not None]
            neighbors = [value for _, value in records]
            attrs = [self._gnn_link_features(neighbor) for neighbor, _ in records]
            missing = 4 - (recipient is not None) - len(neighbors)
            if missing:
                # Keep single-node CUDA fault arithmetic unchanged.
                fill = self._fault_message(self.current_fault_node_state(recipient))
                neighbors += [fill] * missing
                attrs += [[1., 1.]] * missing
            offset = len(all_x)
            offsets.append(offset)
            all_x.extend([raw, *[value[:raw_dim] for value in neighbors]])
            all_edges[0].extend(range(offset + 1, offset + 1 + len(neighbors)))
            all_edges[1].extend([offset] * len(neighbors))
            all_attrs.extend(attrs)
            recipes.append((raw, neighbors, attrs))
        cache, key, numeric = _message_prepare_batch(encoder, recipes, kind)
        if numeric is not None:
            return _message_reconstruct_batch(self, recipes, numeric, version, model_version)
        x = torch.tensor(all_x, dtype=torch.float, device=device)
        edges = torch.tensor(all_edges, dtype=torch.long, device=device)
        attrs = (None if kind == 'sage' else
                 torch.tensor(all_attrs, dtype=torch.float, device=device).reshape(-1, 2))
        with torch.no_grad():
            packed = _message_batch_graph(encoder, x, edges, attrs, offsets, recipes,
                                          raw_dim, hidden_dim, kind, all_edges)
            if packed is not None:
                result = _message_reconstruct_batch(self, recipes, packed, version, model_version)
            else:
                first = encoder.aggregate_stage(x, edges, 1, attrs)
                # Preserve the validated SAGE gather and GAT/JK per-graph reads.
                first_values = first[offsets].cpu().tolist() if kind == 'sage' else None
                hidden = []
                for index, (offset, (_, neighbors, _)) in enumerate(zip(offsets, recipes)):
                    local = first_values[index] if kind == 'sage' else first[offset].cpu().tolist()
                    hidden.extend([local, *[value[raw_dim:raw_dim + hidden_dim] for value in neighbors]])
                h = torch.tensor(hidden, dtype=torch.float, device=device)
                second = encoder.aggregate_stage(h, edges, 2, attrs)
                second_values = second[offsets].cpu().tolist() if kind == 'sage' else None
                result = []
                for index, (offset, (raw, neighbors, attributes)) in enumerate(zip(offsets, recipes)):
                    layer1, layer2 = first[offset], second[offset]
                    if hasattr(encoder, 'combine_hops'):
                        # Batching this projection changes rounding; keep it 1-D.
                        layer2 = encoder.combine_hops(x[offset], layer1, layer2)
                    raw_trace = (0, tuple(raw), self.env.now, version)
                    trace1 = (1, raw_trace, tuple(m.trace[0] for m in neighbors),
                              self.env.now, version, model_version, tuple(attributes))
                    trace2 = (2, trace1, tuple(m.trace[1] for m in neighbors),
                              self.env.now, version, model_version, tuple(attributes))
                    local = first_values[index] if kind == 'sage' else layer1.cpu().tolist()
                    final = second_values[index] if kind == 'sage' else layer2.cpu().tolist()
                    result.append(GraphSAGEMessage(raw + local + final, (raw_trace, trace1, trace2), model_version))
        _message_remember_batch(cache, key, result, recipes)
        return result

    def aggregate_gnn_message(self, raw_value, version, recipient=None):
        encoder = getattr(self, 'gnn_cycle_encoder', self.gnn)
        model_version = getattr(encoder, 'model_version', 0)
        cache = getattr(self, 'gnn_pipeline_messages', {})
        records = [(neighbor, value) for neighbor in self.neighbors if neighbor != recipient
                   for value in [self._fresh_message(cache, neighbor, version)]
                   if value is not None]
        neighbors = [value for _, value in records]
        attributes = [self._gnn_link_features(neighbor) for neighbor, _ in records]
        missing = 4 - (recipient is not None) - len(neighbors)
        if missing:
            fill = self._fault_message(self.current_fault_node_state(recipient))
            neighbors += [fill] * missing
            attributes += [[1., 1.]] * missing
        device = next(encoder.parameters()).device
        edges = torch.tensor([list(range(1, len(neighbors) + 1)), [0] * len(neighbors)],
                             dtype=torch.long, device=device)
        raw_dim = encoder.conv1.in_channels
        hidden_dim = encoder.conv1.out_channels
        x = torch.tensor([raw_value, *[m[:raw_dim] for m in neighbors]],
                         dtype=torch.float, device=device)
        with torch.no_grad():
            edge_attr = torch.tensor(attributes, dtype=torch.float, device=device).reshape(-1, 2)
            layer1 = encoder.aggregate_stage(x, edges, layer=1, edge_attr=edge_attr)[0]
            h = torch.tensor([layer1.cpu().tolist(),
                              *[m[raw_dim:raw_dim + hidden_dim] for m in neighbors]],
                             dtype=torch.float, device=device)
            layer2 = encoder.aggregate_stage(h, edges, layer=2, edge_attr=edge_attr)[0]
            if hasattr(encoder, 'combine_hops'):
                layer2 = encoder.combine_hops(x[0], layer1, layer2)
        raw_trace = (0, tuple(raw_value), self.env.now, version)
        trace1 = (1, raw_trace, tuple(m.trace[0] for m in neighbors),
                  self.env.now, version, model_version, tuple(attributes))
        trace2 = (2, trace1, tuple(m.trace[1] for m in neighbors),
                  self.env.now, version, model_version, tuple(attributes))
        return GraphSAGEMessage(raw_value + layer1.cpu().tolist() + layer2.cpu().tolist(),
                                (raw_trace, trace1, trace2), model_version)

    def _batch_gnn_messages(self, version, recipients, kind):
        if not _message_node_getters_eligible(self) or not _message_graph_supported():
            return self._message_reference_batch(version, recipients, kind)
        dispatch = _message_dispatch_for_environment(self.env)
        return dispatch(self, version, recipients, kind)

    def gnn_embedding_exchanger(self):
        # One packed message per tick; aggregation reads prior delivered messages.
        version = math.floor(self.env.now / self.state_update_period + 1e-9) + 1
        wait = version * self.state_update_period - self.env.now
        if wait > 1e-9:
            yield self.env.timeout(wait)
        while self.active:
            self.gnn_cycle_version = version
            self.gnn_cycle_encoder = self.gnn.communication_snapshot(self.env, version)
            kind = _message_batch_kind(self.gnn_cycle_encoder)
            neighbors = sorted(set(self.neighbors) | self.pending_state_neighbors)
            if kind is None:
                self.gnn_local_message = self.aggregate_gnn_message(self.current_gnn_raw_state(), version)
                for neighbor in neighbors:
                    message = self.aggregate_gnn_message(self.current_gnn_raw_state(), version, recipient=neighbor)
                    self.env.process(self.send_gnn_message(neighbor, version, message))
            else:
                outgoing = self._batch_gnn_messages(version, [None, *neighbors], kind)
                self.gnn_local_message = outgoing[0]
                for neighbor, message in zip(neighbors, outgoing[1:]):
                    self.env.process(self.send_gnn_message(neighbor, version, message))
            self.gnn_active_version = version
            self.encode_data = None
            version += 1
            yield self.env.timeout(version * self.state_update_period - self.env.now)

    def get_current_state(self, destination, hops, is_computed, mission_state):
        state = super().get_current_state(destination, hops, is_computed, mission_state)
        cache = getattr(self, 'gnn_pipeline_messages', {})
        slots = getattr(self, 'action_neighbors', self.neighbors + [None] * (4 - len(self.neighbors)))
        values = [self._fresh_message(cache, neighbor, self.gnn_cycle_version,
                                      previous_only=False)
                  if neighbor in self.neighbors else None for neighbor in slots]
        if any(value is None for value in values):
            fill = self._fault_message()
            values = [fill if value is None else value for value in values]
        data = self.gnn.replay_data(values)
        if is_computed:
            # Mask physical compute inputs for this packet, then re-encode.
            # Hidden coordinates are learned and cannot be zeroed by position.
            data.x[:, 2:4] = 0
            if data.x.size(1) == 6:
                data.x[:, 5] = 0
            encoder = getattr(self, 'gnn_cycle_encoder', self.gnn)
            with torch.no_grad():
                # Keep replay records on CPU; use the encoder device only for inference.
                embeddings = _message_reencode_graph(encoder, data)
                if embeddings is None:
                    encoder_data = data.clone().to(next(encoder.parameters()).device)
                    embeddings = encoder(encoder_data)[:4].reshape(1, -1).cpu()
                data.decision_embeddings = embeddings
            state[1][10:13 if data.x.size(1) == 6 else 12] = 0
        state[0] = data
        return state

    def construct_gnn_graph(self):
        # Task/link/distance fields still come from the base state builder.
        return {}, []

    def encode_for_GNN(self, nodes, edges):
        return Data()


GraphSAGEEncoder.satellite_class = GraphSAGESatellite


_message_warmup_streams = weakref.WeakKeyDictionary()
_message_warmup_stream_counts = dict(requests=0, created=0, reused=0, device_changes=0)
_message_environment_runtimes = weakref.WeakKeyDictionary()


@contextmanager
def _message_replace_attribute(owner, name, replacement):
    previous = getattr(owner, name)
    setattr(owner, name, replacement)
    try:
        yield
    finally:
        setattr(owner, name, previous)


def _message_shared_warmup_stream(source, device):
    device = torch.device(device)
    if device.type != 'cuda':
        raise ValueError('Shared message warmup streams require CUDA')
    if device.index is None:
        device = torch.device('cuda', torch.cuda.current_device())
    _message_warmup_stream_counts['requests'] += 1
    entry = _message_warmup_streams.get(source)
    if entry is not None and entry[0] == device:
        _message_warmup_stream_counts['reused'] += 1
        return entry[1]
    stream = torch.cuda.Stream(device=device)
    _message_warmup_streams[source] = (device, stream)
    _message_warmup_stream_counts['created'] += 1
    _message_warmup_stream_counts['device_changes'] += entry is not None
    return stream


def _message_dispatch_for_environment(env):
    runtime = _message_environment_runtimes.get(env)
    if runtime is None:
        context = _message_grouped_context(chunks=True, shared_streams=True)
        dispatch, counts = context.__enter__()
        # State uses env identity, never a strong env backlink. Finalization
        # closes source pools and chunk owner backlinks after the simulator dies.
        cleanup = weakref.finalize(env, context.__exit__, None, None, None)
        runtime = (dispatch, counts, cleanup)
        _message_environment_runtimes[env] = runtime
    return runtime[0]


# Bind audited methods once in this exact module instance, including __main__.
_message_getter_functions = {
    name: getattr(GraphSAGESatellite, name) for name in (
        'current_gnn_raw_state', 'current_fault_node_state', '_fresh_message',
        '_gnn_link_features', '_normalized_compute_ability',
        '_normalized_compute_time', '_normalized_mean_transmission_wait',
        '_normalized_compute_completion_time', '_normalized_link_transmission_wait',
        '_normalized_transmission_wait', '_remaining_transmission_time')}


def _message_node_getters_eligible(value):
    from inspect import getattr_static
    if not _message_satellite_type_eligible(value, GraphSAGESatellite, sys.modules['training_runner']):
        return False
    # Static resolution never invokes an overridden getter or property.
    return all(name not in vars(value) and getattr_static(value, name) is function
               for name, function in _message_getter_functions.items())


def _message_satellite_type_eligible(value, base, runner):
    from types import FunctionType
    cls = type(value)
    if cls is base:
        return True
    if (cls.__name__ != 'AcceleratedSatellite' or cls.__module__ != runner.__name__
            or cls.__bases__ != (base,)):
        return False
    expected = {'build_routing_table', '_speed_eager_routes', 'routing_tables', 'neighbor_hops'}
    owned = set(vars(cls)) - {'__module__', '__doc__'}
    if owned != expected:
        return False
    if (cls.build_routing_table is not runner._speed_defer_routes
            or (cls._speed_eager_routes is not runner._speed_routing_table and cls._speed_eager_routes is not base.build_routing_table)):
        return False
    for name in ('routing_tables', 'neighbor_hops'):
        actual = vars(cls)[name]
        reference = runner._speed_route_property(name)
        if not isinstance(actual, property):
            return False
        for left, right in ((actual.fget, reference.fget), (actual.fset, reference.fset), (actual.fdel, reference.fdel)):
            if left is None or right is None:
                if left is not right:
                    return False
            elif (not isinstance(left, FunctionType) or not isinstance(right, FunctionType)
                    or left.__code__ is not right.__code__ or left.__globals__ is not right.__globals__
                    or tuple(cell.cell_contents for cell in (left.__closure__ or ())) != tuple(cell.cell_contents for cell in (right.__closure__ or ()))):
                return False
    return True

def _message_fused_context(deferred=False, warmup_stream=None):
    """Diagnostic: retain original per-call shapes inside one fault+normal graph."""
    from collections import OrderedDict
    from contextlib import contextmanager, ExitStack
    from copy import deepcopy
    from weakref import WeakKeyDictionary
    native = sys.modules[__name__]
    from ablation.message_aggregation import GATMessageEncoder
    original = GraphSAGESatellite._message_reference_batch
    pools = WeakKeyDictionary()
    chunk_owners = WeakKeyDictionary()
    counts = dict(calls=0, captures=0, replays=0, faults=0, fallbacks=0, normal_cache_hits=0, getter_guard_fallbacks=0, getter_reuse_dispatches=0)

    # Fixed audited getters only; an override retains the original path.
    getter_functions = _message_getter_functions

    def fault_from_valid(self, valid):
        raw_dim = self.gnn.conv1.in_channels
        if not valid:
            return [1, 0, 0, 1, 1] + ([0] if raw_dim == 6 else [])
        factor = self.fault_fill_multiplier
        use_mean = getattr(self, 'fault_compute_double_mean', True)
        means = [sum((value[i] for value in valid)) / len(valid) for i in (2, 3, 4)]
        clip = native.simulation._clip_normalized
        ability = clip(means[0] / factor) if use_mean else 0
        wait = clip(means[1] * factor) if use_mean else 1
        transmission = clip(means[2] * (factor if use_mean else 2))
        result = [1, 0, ability, wait, transmission]
        if raw_dim == 6:
            result.append(clip(sum((value[5] for value in valid)) / len(valid) / factor) if use_mean else 0)
        return result

    def dispatch(self, version, recipients, kind):
        if (not _message_node_getters_eligible(self) or not recipients
                or version != getattr(self, 'gnn_cycle_version', None)):
            counts['getter_guard_fallbacks'] += 1
            return original(self, version, recipients, kind)
        encoder = self.gnn_cycle_encoder
        origin = native._message_origins.get(encoder)
        source = None if origin is None else origin[0]()
        gat = isinstance(encoder, GATMessageEncoder)
        expected = (dict(aggr='add', flow='source_to_target', heads=1, concat=False,
                         negative_slope=.2, dropout=0., add_self_loops=True,
                         fill_value='mean', residual=False) if gat else
                    dict(aggr='mean', flow='source_to_target', normalize=False,
                         root_weight=True, project=False))
        fixed = all(getattr(conv, name, None) == value
                    for conv in (encoder.conv1, encoder.conv2) for name, value in expected.items())
        if (source is None or not native._message_graph_supported()
                or not fixed
                or native._message_batch_kind(encoder) != kind
                or origin[2] != native._message_signature(encoder)):
            counts['fallbacks'] += 1
            return original(self, version, recipients, kind)
        counts['calls'] += 1
        device = next(encoder.parameters()).device
        hidden, raw_dim = encoder.conv1.out_channels, encoder.conv1.in_channels
        model_version = getattr(encoder, 'model_version', 0)
        histories = getattr(self, 'gnn_pipeline_messages', {})
        recipes, xs, hs, attrs, offsets = [], [], [], [], []
        edges, fault_raw, fault_slots = [[], []], [], []
        fault_keys, pending_faults, fault_fills = [], {}, {}
        fault_cache = native._message_cache(encoder)
        raw_base = self.current_gnn_raw_state()
        delivered = [(neighbor, value, self._gnn_link_features(neighbor))
                     for neighbor in self.neighbors
                     for value in [self._fresh_message(histories, neighbor, version)]
                     if value is not None]
        counts['getter_reuse_dispatches'] += 1
        for recipient in recipients:
            raw = raw_base.copy()
            records = [(neighbor, value, link) for neighbor, value, link in delivered
                       if neighbor != recipient]
            neighbors = [value for _, value, _ in records]
            attributes = [link.copy() for _, _, link in records]
            missing = 4 - (recipient is not None) - len(neighbors)
            offset = len(xs)
            if missing:
                value = fault_from_valid(self, neighbors)
                raw_trace = (0, tuple(value), self.env.now, self.gnn_cycle_version)
                trace1 = (1, raw_trace, (), self.env.now, self.gnn_cycle_version, model_version)
                trace2 = (2, trace1, (), self.env.now, self.gnn_cycle_version, model_version)
                fault_key = native.struct.pack(f'{len(value)}f', *value)
                cached = None if fault_cache is None else fault_cache.get(fault_key)
                fill = native.GraphSAGEMessage(value + (list(cached) if cached is not None else [0.] * (2 * hidden)),
                    (raw_trace, trace1, trace2), model_version)
                if cached is None:
                    fault_fills.setdefault(fault_key, []).append(fill)
                    if fault_key not in pending_faults:
                        pending_faults[fault_key] = len(fault_raw)
                        fault_raw.append(value)
                        fault_keys.append(fault_key)
                        fault_slots.append([])
                    fault_slots[pending_faults[fault_key]].extend(range(offset + 1 + len(neighbors),
                                                               offset + 1 + len(neighbors) + missing))
                else:
                    fault_cache.move_to_end(fault_key)
                neighbors += [fill] * missing
                attributes += [[1., 1.]] * missing
            offsets.append(offset)
            xs.extend([raw, *[value[:raw_dim] for value in neighbors]])
            hs.extend([[0.] * hidden, *[value[raw_dim:raw_dim + hidden] for value in neighbors]])
            attrs.extend(attributes)
            edges[0].extend(range(offset + 1, offset + 1 + len(neighbors)))
            edges[1].extend([offset] * len(neighbors))
            recipes.append((raw, neighbors, attributes))
        cache, numeric_key = None, None
        if not fault_keys:
            cache, numeric_key, numeric = native._message_prepare_batch(encoder, recipes, kind)
            if numeric is not None:
                counts['normal_cache_hits'] += 1
                return native._message_reconstruct_batch(self, recipes, numeric, version, model_version)
        shapes = dict(x=(len(xs), raw_dim), h=(len(hs), hidden),
                      attrs=(len(attrs), 2), fault=(len(fault_raw), raw_dim))
        values = list(chain.from_iterable(chain.from_iterable((xs, hs, attrs, fault_raw))))
        try:
            packed = native.struct.pack(f'{len(values)}f', *values)
        except OverflowError:
            counts['fallbacks'] += 1
            return original(self, version, recipients, kind)
        array = np.frombuffer(packed, dtype=np.float32)
        if not np.isfinite(array).all():
            counts['fallbacks'] += 1
            return original(self, version, recipients, kind)
        tensor = torch.from_numpy(array.copy())
        cpu, offset = {}, 0
        for name, shape in shapes.items():
            size = shape[0] * shape[1]
            cpu[name] = tensor[offset:offset + size].view(shape)
            offset += size
        key = (type(encoder), tuple(offsets), tuple(map(tuple, edges)), tuple(map(tuple, fault_slots)),
               tuple((name, tuple(value.shape)) for name, value in cpu.items()),
               repr(encoder.conv1), repr(encoder.conv2))
        pool = pools.setdefault(source, OrderedDict())
        bank = pool.get(key)
        if bank is None:
            with torch.random.fork_rng(devices=[device.index]):
                prepared = deepcopy(encoder).eval().requires_grad_(False)
            if gat:
                prepared.conv1.add_self_loops = prepared.conv2.add_self_loops = False
            size, starts = 0, {}
            for name, value in cpu.items():
                size = (size + 63) // 64 * 64
                starts[name] = size
                size += value.numel()
            host = torch.zeros(size, dtype=torch.float32, pin_memory=True)
            host_views = {name: host[starts[name]:starts[name] + value.numel()].view(value.shape)
                          for name, value in cpu.items()}
            for name, value in cpu.items():
                host_views[name].copy_(value)
            gpu = host.to(device, non_blocking=deferred != 'prepare')
            inputs = {name: gpu[starts[name]:starts[name] + value.numel()].view(value.shape)
                      for name, value in cpu.items()}
            edge = torch.tensor(edges, dtype=torch.long, device=device)
            empty = torch.empty((2, 0), dtype=torch.long, device=device)
            indices = torch.tensor(offsets, dtype=torch.long, device=device)
            kept = []

            def operation():
                import torch_geometric.nn.conv.gat_conv as gat_module
                fault_edge, fault_attr = empty, None
                if gat and fault_slots:
                    fault_edge, fault_attr = gat_module.add_self_loops(empty,
                        inputs['x'].new_zeros((0, 2)), fill_value=prepared.conv1.fill_value, num_nodes=1)
                fault_outputs = []
                for index, slots in enumerate(fault_slots):
                    raw = inputs['fault'][index:index + 1]
                    first = prepared.aggregate_stage(raw, fault_edge, 1, fault_attr)
                    second = prepared.aggregate_stage(first, fault_edge, 2, fault_attr)
                    if hasattr(prepared, 'combine_hops'):
                        second = prepared.combine_hops(raw, first, second)
                    fault_outputs.append((first, second))
                    for slot in slots:
                        inputs['h'][slot].copy_(first[0])
                ge, ga = edge, inputs['attrs'] if gat else None
                if gat:
                    ge, ga = gat_module.add_self_loops(edge, ga,
                        fill_value=prepared.conv1.fill_value, num_nodes=len(xs))
                first = prepared.aggregate_stage(inputs['x'], ge, 1, ga)
                inputs['h'].index_copy_(0, indices, first.index_select(0, indices))
                second = prepared.aggregate_stage(inputs['h'], ge, 2, ga)
                combined = ([prepared.combine_hops(inputs['x'][o], first[o], second[o]) for o in offsets]
                            if hasattr(prepared, 'combine_hops') else None)
                kept[:] = fault_outputs
                normal = native._message_pack_outputs(first, second, combined, indices)
                return torch.cat([normal.reshape(-1), *[
                    torch.cat((a[0], b[0])) for a, b in fault_outputs]])

            with torch.no_grad(), ExitStack() as stack:
                fault_resources = stack.enter_context(native._message_capture_scope(prepared, empty, [[], []], 1))
                normal_resources = stack.enter_context(native._message_capture_scope(prepared, edge, edges, len(xs)))
                stream = (torch.cuda.Stream(device=device) if warmup_stream is None
                          else warmup_stream(source, device))
                stream.wait_stream(torch.cuda.current_stream(device))
                with torch.cuda.stream(stream):
                    for _ in range(3):
                        operation()
                torch.cuda.current_stream(device).wait_stream(stream)
                graph = torch.cuda.CUDAGraph()
                with torch.cuda.graph(graph):
                    out = operation()
                resources = fault_resources() + normal_resources()
            bank = dict(model=prepared, host=host, host_views=host_views, gpu=gpu,
                        inputs=inputs, edge=edge, empty=empty, indices=indices, graph=graph,
                        out=out, resources=resources, kept=tuple(kept), generation=origin[1],
                        operation=operation, edge_lists=edges, nodes=len(xs), get_kept=lambda: tuple(kept),
                        stream=stream, chunk_owner=chunk_owners.setdefault(source, OrderedDict()),
                        resident=True)
            pool[key] = bank
            if len(pool) > 32:
                _, expired = pool.popitem(last=False)
                expired['resident'] = False
                expired['chunk_owner'].pop(id(expired), None)
                # Pending plans keep all bank/chunk resources until completion.
            counts['captures'] += 1
        else:
            for name, value in cpu.items():
                bank['host_views'][name].copy_(value)
            if deferred != 'prepare':
                bank['gpu'].copy_(bank['host'], non_blocking=True)
            if bank['generation'] != origin[1]:
                bank['model'].load_state_dict(encoder.state_dict())
                bank['generation'] = origin[1]
        pool.move_to_end(key)
        if deferred != 'prepare':
            bank['graph'].replay()
        width = 2 * hidden
        normal_size = len(recipients) * width
        def finish(flat):
            values = [flat[index:index + width] for index in range(0, normal_size, width)]
            output_cache, output_key = cache, numeric_key
            for index, fault_key in enumerate(fault_keys):
                start = normal_size + index * width
                for fill in fault_fills[fault_key]:
                    fill[raw_dim:] = flat[start:start + width]
            if fault_cache is not None:
                for index, fault_key in enumerate(fault_keys):
                    start = normal_size + index * width
                    fault_cache[fault_key] = tuple(flat[start:start + width])
                    if len(fault_cache) > 4096:
                        fault_cache.popitem(last=False)
            if fault_keys:
                output_cache, output_key, _ = native._message_prepare_batch(encoder, recipes, kind)
            result = native._message_reconstruct_batch(self, recipes, values, version, model_version)
            native._message_remember_batch(output_cache, output_key, result, recipes)
            return result
        counts['replays'] += 1
        counts['faults'] += len(fault_raw)
        if deferred == 'prepare':
            def launch(upload):
                bank['gpu'].copy_(upload)
                bank['graph'].replay()
                return bank['out'].clone()
            return dict(input=bank['host'].clone(), launch=launch, finish=finish,
                        dedup_key=(id(cache), numeric_key) if cache is not None and not fault_keys else None,
                        bank=bank)
        if deferred:
            return dict(output=bank['out'].clone(), finish=finish)
        return finish(bank['out'].cpu().tolist())

    @contextmanager
    def context():
        try:
            if deferred:
                yield dispatch, counts
            else:
                with _message_replace_attribute(GraphSAGESatellite, '_batch_gnn_messages', dispatch):
                    yield counts
        finally:
            # Break owner backlinks only; externally retained plans keep their
            # model, graph, tensors and chunk payload intact.
            for pool in tuple(pools.values()):
                for bank in pool.values():
                    bank['resident'] = False
            for owner in tuple(chunk_owners.values()):
                owner.clear()
    return context()

def _message_launch_homogeneous_plans(plans, upload, counts):
    """Diagnostic fixed-eight replay; keep each original node operation intact.

    Banks own one optional chunk graph and expose operation, model, gpu, out,
    empty, edge, edge_lists, nodes, and the operation's mutable kept list.
    Upload contains plan inputs in their original order. Results retain that
    order even though independent GPU work is grouped by bank identity.
    """
    from contextlib import ExitStack
    native = sys.modules[__name__]

    width = 8
    names = ('chunk_captures', 'chunk_replays', 'chunk_plans', 'chunk_tail_plans',
             'chunk_capture_allocated_bytes', 'chunk_capture_reserved_bytes', 'chunk_evictions')
    for name in names:
        counts.setdefault(name, 0)
    outputs, buckets, offset = [None] * len(plans), {}, 0
    for index, plan in enumerate(plans):
        size = plan['input'].numel()
        buckets.setdefault(id(plan['bank']), []).append((index, offset, offset + size))
        offset += size
    if offset != upload.numel():
        raise ValueError('Homogeneous upload must contain exactly the plan inputs')

    for entries in buckets.values():
        bank = plans[entries[0][0]]['bank']
        full = (len(entries) // width * width if bank.get('resident', True) else 0)
        if full:
            bank['chunk_seen'] = bank.get('chunk_seen', 0) + 1
        if not full or bank['chunk_seen'] < 2:
            full = 0
        owner = bank['chunk_owner']
        if full and 'chunk8' not in bank and len(owner) >= 2:
            least = min(owner, key=lambda key: owner[key]['chunk_seen'])
            if bank['chunk_seen'] <= owner[least]['chunk_seen']:
                full = 0
        for start in range(0, full, width):
            block = entries[start:start + width]
            # One gather and one copy replace eight Python-issued bank copies.
            gathered = torch.stack([upload[left:right] for _, left, right in block])
            chunk = bank.get('chunk8')
            if chunk is None:
                if len(owner) >= 2:
                    least = min(owner, key=lambda key: owner[key]['chunk_seen'])
                    expired = owner.pop(least)
                    expired.pop('chunk8', None)
                    counts['chunk_evictions'] += 1
                operation, node_input = bank['operation'], bank['gpu']
                static_input = gathered.clone()
                static_output = bank['out'].new_empty((width, *bank['out'].shape))
                kept = bank['kept']
                get_kept = bank.get('get_kept')
                captured_outputs = []

                def body():
                    values = []
                    for slot in range(width):
                        node_input.copy_(static_input[slot])
                        value = operation()
                        static_output[slot].copy_(value)
                        values.append(value)
                    captured_outputs[:] = values

                device = node_input.device
                torch.cuda.synchronize(device)
                allocated = torch.cuda.memory_allocated(device)
                reserved = torch.cuda.memory_reserved(device)
                with torch.no_grad(), ExitStack() as stack:
                    fault_resources = stack.enter_context(native._message_capture_scope(
                        bank['model'], bank['empty'], [[], []], 1))
                    normal_resources = stack.enter_context(native._message_capture_scope(
                        bank['model'], bank['edge'], bank['edge_lists'], bank['nodes']))
                    stream = bank['stream']
                    stream.wait_stream(torch.cuda.current_stream(device))
                    with torch.cuda.stream(stream):
                        for _ in range(3):
                            body()
                    torch.cuda.current_stream(device).wait_stream(stream)
                    graph = torch.cuda.CUDAGraph()
                    with torch.cuda.graph(graph):
                        body()
                    resources = fault_resources() + normal_resources()
                    retained = tuple(get_kept() if get_kept is not None else kept)
                torch.cuda.synchronize(device)
                allocated_delta = max(0, torch.cuda.memory_allocated(device) - allocated)
                reserved_delta = max(0, torch.cuda.memory_reserved(device) - reserved)
                # No callable here captures bank: its LRU owner releases both graphs.
                chunk = dict(input=static_input, output=static_output, graph=graph,
                             resources=resources, kept=retained,
                             captured_outputs=tuple(captured_outputs),
                             allocated_bytes=allocated_delta, reserved_bytes=reserved_delta)
                bank['chunk8'] = chunk
                owner[id(bank)] = bank
                counts['chunk_captures'] += 1
                counts['chunk_capture_allocated_bytes'] += allocated_delta
                counts['chunk_capture_reserved_bytes'] += reserved_delta
            else:
                chunk['input'].copy_(gathered)
                bank['chunk_owner'].move_to_end(id(bank))
            chunk['graph'].replay()
            result = chunk['output'].clone()
            for slot, (index, _, _) in enumerate(block):
                outputs[index] = result[slot]
            counts['chunk_replays'] += 1
            counts['chunk_plans'] += width
        for index, left, right in entries[full:]:
            outputs[index] = plans[index]['launch'](upload[left:right])
            counts['chunk_tail_plans'] += 1
    return outputs

def _message_grouped_context(chunks=False, shared_streams=False):
    """Diagnostic lookahead; SimPy events themselves retain their original order."""
    from contextlib import contextmanager, ExitStack
    native = sys.modules[__name__]
    original = GraphSAGESatellite._message_reference_batch

    def fingerprint(node):
        return (tuple(node.neighbors), tuple(sorted(node.pending_state_neighbors)),
                native.struct.pack('6d', *node.current_gnn_raw_state()),
                tuple((key, tuple((v, t, id(value), native.struct.pack(f'{len(value)}d', *value))
                                  for v, t, value in records))
                      for key, records in getattr(node, 'gnn_pipeline_messages', {}).items()),
                tuple(native.struct.pack('2d', *node._gnn_link_features(neighbor)) for neighbor in node.neighbors),
                (node.fault_fill_multiplier, getattr(node, 'fault_compute_double_mean', True)),
                native._message_signature(node.gnn_cycle_encoder))

    @contextmanager
    def prepare_memo(encoder, counts):
        signature_fn = native._message_signature
        kind_fn = native._message_batch_kind
        cache_fn = native._message_cache
        counts['signature_real_prepare_scans'] += 1
        signature = signature_fn(encoder)
        kind = kind_fn(encoder)
        origin = native._message_origins.get(encoder)
        if (kind is None or origin is None or origin[0]() is None
                or origin[2] != signature):
            counts['memo_invalid_scopes'] += 1
            yield
            return
        def signature_once(value):
            if value is encoder:
                counts['signature_memo_hits'] += 1
                return signature
            return signature_fn(value)
        def kind_once(value):
            if value is encoder:
                counts['kind_memo_hits'] += 1
                return kind
            return kind_fn(value)
        with ExitStack() as memo:
            memo.enter_context(_message_replace_attribute(native, '_message_signature', signature_once))
            memo.enter_context(_message_replace_attribute(native, '_message_batch_kind', kind_once))
            cache = cache_fn(encoder)
            def cache_once(value):
                if value is encoder:
                    counts['cache_memo_hits'] += 1
                    return cache
                return cache_fn(value)
            memo.enter_context(_message_replace_attribute(native, '_message_cache', cache_once))
            counts['memo_valid_scopes'] += 1
            yield

    @contextmanager
    def context():
        prepared = {}
        prepared_tick = None
        counts = dict(groups=0, prefetched=0, reused=0, invalidated=0, deduplicated=0, discarded=0, stale_scans=0, stale_checked_keys=0,
                      signature_real_prepare_scans=0, signature_memo_hits=0,
                      kind_memo_hits=0, cache_memo_hits=0, memo_valid_scopes=0,
                      memo_invalid_scopes=0)
        with ExitStack() as stack:
            warmup_stream = None
            if shared_streams:
                warmup_stream = _message_shared_warmup_stream
                counts['warmup_streams'] = _message_warmup_stream_counts
            submit, fused_counts = stack.enter_context(_message_fused_context(
                deferred='prepare', warmup_stream=warmup_stream))
            def dispatch(self, version, recipients, kind):
                nonlocal prepared_tick
                if not _message_node_getters_eligible(self):
                    return original(self, version, recipients, kind)
                tick = (id(self.env), self.env.now, version)
                if tick != prepared_tick:
                    counts['stale_scans'] += 1
                    counts['stale_checked_keys'] += len(prepared)
                    stale = [key for key in prepared if key[1:3] != (self.env.now, version)]
                    for old in stale:
                        del prepared[old]
                    counts['discarded'] += len(stale)
                    prepared_tick = tick
                key = (id(self), self.env.now, version, tuple(recipients))
                if key in prepared:
                    expected, result = prepared.pop(key)
                    if fingerprint(self) == expected:
                        counts['reused'] += 1
                        return result
                    counts['invalidated'] += 1
                    return original(self, version, recipients, kind)
                targets = [(self, recipients)]
                for at, priority, eid, event in sorted(self.env._queue):
                    if at != self.env.now:
                        break
                    callbacks = getattr(event, 'callbacks', None) or []
                    process = getattr(callbacks[0], '__self__', None) if len(callbacks) == 1 else None
                    generator = getattr(process, '_generator', None)
                    code = getattr(generator, 'gi_code', None)
                    node = None if code is None else generator.gi_frame.f_locals.get('self')
                    if (code is native.simulation.Satellite_with_Computing.state_exchanger.__code__
                            and node is not None and node.aligned_graphsage_policy
                            and node.gnn_node_feature_dim == 6):
                        continue
                    if (code is None or code.co_name != 'gnn_embedding_exchanger' or node is None
                            or generator.gi_frame.f_locals.get('version') != version):
                        break
                    if not _message_node_getters_eligible(node):
                        break
                    if node.gnn is not self.gnn or not node.active:
                        break
                    targets.append((node, [None, *sorted(set(node.neighbors) | node.pending_state_neighbors)]))
                with prepare_memo(self.gnn_cycle_encoder, counts):
                    pending = []
                    for node, destinations in targets:
                        had_version = hasattr(node, 'gnn_cycle_version')
                        had_encoder = hasattr(node, 'gnn_cycle_encoder')
                        old_version = getattr(node, 'gnn_cycle_version', None)
                        old_encoder = getattr(node, 'gnn_cycle_encoder', None)
                        try:
                            node.gnn_cycle_version = version
                            node.gnn_cycle_encoder = node.gnn.communication_snapshot(node.env, version)
                            expected = fingerprint(node)
                            value = submit(node, version, destinations, kind)
                            pending.append((node, destinations, expected, value))
                        finally:
                            if had_version:
                                node.gnn_cycle_version = old_version
                            else:
                                del node.gnn_cycle_version
                            if had_encoder:
                                node.gnn_cycle_encoder = old_encoder
                            else:
                                del node.gnn_cycle_encoder
                    plans = [entry[3] for entry in pending if isinstance(entry[3], dict)]
                    unique, keys = [], {}
                    for plan in plans:
                        dedup_key = plan['dedup_key']
                        if dedup_key is not None and dedup_key in keys:
                            plan['shared'] = keys[dedup_key]
                            counts['deduplicated'] += 1
                        else:
                            plan['shared'] = len(unique)
                            unique.append(plan)
                            if dedup_key is not None:
                                keys[dedup_key] = plan['shared']
                    if plans:
                        host = torch.cat([plan['input'] for plan in unique]).pin_memory()
                        upload = host.to(next(self.gnn.parameters()).device, non_blocking=True)
                        if chunks:
                            for plan, output in zip(unique, _message_launch_homogeneous_plans(unique, upload, counts)):
                                plan['output'] = output
                        else:
                            offset = 0
                            for plan in unique:
                                size = plan['input'].numel()
                                plan['output'] = plan['launch'](upload[offset:offset + size])
                                offset += size
                    outputs = [plan['output'] for plan in unique]
                    flat = torch.cat(outputs).cpu().tolist() if outputs else []
                    slices, offset = [], 0
                    for output in outputs:
                        slices.append((offset, offset + output.numel()))
                        offset += output.numel()
                    for node, destinations, expected, value in pending:
                        if isinstance(value, dict):
                            start, end = slices[value['shared']]
                            value = value['finish'](flat[start:end])
                        prepared[(id(node), node.env.now, version, tuple(destinations))] = (expected, value)
                counts['groups'] += 1
                counts['prefetched'] += len(targets)
                counts['fused'] = fused_counts
                expected, result = prepared.pop(key)
                assert expected == fingerprint(self)
                return result
            yield dispatch, counts
    return context()


def build_shared_config(encoder_name, seed=0):
    config = training_entry.build_config(encoder_name, seed)
    config['agent']['gnn_factory'] = GraphSAGEEncoder
    return config


TRAINING_SEEDS = training_entry.TRAINING_SEEDS
CONFIG = build_shared_config('graphsage')


def seed_config(seed):
    return build_shared_config('graphsage', seed)


def main():
    from training_runner import prepare_reproducible_process

    prepare_reproducible_process()
    parser = argparse.ArgumentParser(description='Train GraphSAGE.')
    parser.add_argument('--seed', type=int, choices=TRAINING_SEEDS)
    args = parser.parse_args()
    selected_seeds = (args.seed,) if args.seed is not None else TRAINING_SEEDS
    torch.set_num_threads(1)
    torch.set_num_interop_threads(1)
    slot_path = training_entry._claim_training_slot()
    try:
        for seed in selected_seeds:
            config = build_shared_config('graphsage', seed)
            training_entry.save_config_snapshot(config)
            run_training(config)
    finally:
        if slot_path is not None:
            slot_path.unlink(missing_ok=True)


if __name__ == '__main__':
    main()
